use gpui::prelude::*;
use kui::components::dialog::Dialog;

let control = cx.new(|cx| Dialog::new("review", "Review changes", "Publish workspace", cx)
        .with_description("Your team will see these changes immediately.")
        .with_cancel("Keep editing").with_confirm("Publish now"));

use gpui::prelude::*;
use kui::components::popover::Popover;

let control = cx.new(|cx| Popover::new("checks", "Why this status?", "Ready for review", cx)
        .with_description("All required checks passed.").with_cancel("Got it"));

use gpui::prelude::*;
use kui::components::tabs::{Tabs, TabPage};

let control = cx.new(|cx| Tabs::new("views", "Workspace views", vec![
        TabPage::new("overview", "Overview", |_, _| gpui::div().child("Workspace overview")),
        TabPage::new("activity", "Activity", |_, _| gpui::div().child("Recent activity")),
    ], cx));

use gpui::prelude::*;
use kui::components::combobox::Combobox;
use kui::primitives::picker::PickerOption;

let control = cx.new(|cx| Combobox::new("model", "Model", vec![
        PickerOption::new("fast", "Fast").with_keywords(["quick"]),
        PickerOption::new("reasoning", "Reasoning"),
    ], window, cx).with_value("fast"));

use gpui::prelude::*;
use kui::components::select::Select;
use kui::primitives::picker::PickerOption;

let control = cx.new(|cx| Select::new("team", "Team", vec![
        PickerOption::new("design", "Design"), PickerOption::new("engineering", "Engineering"),
    ], window, cx).with_value("design"));

